+
+#define DecodeInstruction(fname, fieldname, decoder, InsnType) \
+static DecodeStatus fname(const uint8_t DecodeTable[], MCInst *MI, \
+                                      InsnType insn, uint64_t Address, const void *Decoder) { \
+  const uint8_t *Ptr = DecodeTable; \
+  uint64_t CurFieldValue = 0; \
+  DecodeStatus S = MCDisassembler_Success; \
+  while (true) { \
+    switch (*Ptr) { \
+    default: \
+      return MCDisassembler_Fail; \
+    case MCD_OPC_ExtractField: { \
+      unsigned Start = *++Ptr; \
+      unsigned Len = *++Ptr; \
+      ++Ptr; \
+      CurFieldValue = fieldname(insn, Start, Len); \
+      break; \
+    } \
+    case MCD_OPC_FilterValue: { \
+      /* Decode the field value. */ \
+      unsigned Len; \
+      uint64_t Val = decodeULEB128(++Ptr, &Len); \
+      Ptr += Len; \
+      /* NumToSkip is a plain 24-bit integer. */ \
+      unsigned NumToSkip = *Ptr++; \
+      NumToSkip |= (*Ptr++) << 8; \
+      NumToSkip |= (*Ptr++) << 16; \
+      /* Perform the filter operation. */ \
+      if (Val != CurFieldValue) \
+        Ptr += NumToSkip; \
+      break; \
+    } \
+    case MCD_OPC_CheckField: { \
+      unsigned Start = *++Ptr; \
+      unsigned Len = *++Ptr; \
+      uint64_t FieldValue = fieldname(insn, Start, Len); \
+      /* Decode the field value. */ \
+      unsigned PtrLen = 0; \
+      uint64_t ExpectedValue = decodeULEB128(++Ptr, &PtrLen); \
+      Ptr += PtrLen; \
+      /* NumToSkip is a plain 24-bit integer. */ \
+      unsigned NumToSkip = *Ptr++; \
+      NumToSkip |= (*Ptr++) << 8; \
+      NumToSkip |= (*Ptr++) << 16; \
+      /* If the actual and expected values don't match, skip. */ \
+      if (ExpectedValue != FieldValue) \
+        Ptr += NumToSkip; \
+      break; \
+    } \
+    case MCD_OPC_CheckPredicate: { \
+      unsigned Len; \
+      /* Decode the Predicate Index value. */ \
+      unsigned PIdx = decodeULEB128(++Ptr, &Len); \
+      Ptr += Len; \
+      /* NumToSkip is a plain 24-bit integer. */ \
+      unsigned NumToSkip = *Ptr++; \
+      NumToSkip |= (*Ptr++) << 8; \
+      NumToSkip |= (*Ptr++) << 16; \
+      /* Check the predicate. */ \
+      bool Pred = checkDecoderPredicate(MI, PIdx); \
+      if (!Pred) \
+        Ptr += NumToSkip; \
+      break; \
+    } \
+    case MCD_OPC_Decode: { \
+      unsigned Len; \
+      /* Decode the Opcode value. */ \
+      unsigned Opc = decodeULEB128(++Ptr, &Len); \
+      Ptr += Len; \
+      unsigned DecodeIdx = decodeULEB128(Ptr, &Len); \
+      Ptr += Len; \
+      MCInst_clear(MI); \
+      MCInst_setOpcode(MI, Opc); \
+      bool DecodeComplete; \
+      S = decoder(S, DecodeIdx, insn, MI, Address, Decoder, &DecodeComplete); \
+      return S; \
+    } \
+    case MCD_OPC_TryDecode: { \
+      unsigned Len; \
+      /* Decode the Opcode value. */ \
+      unsigned Opc = decodeULEB128(++Ptr, &Len); \
+      Ptr += Len; \
+      unsigned DecodeIdx = decodeULEB128(Ptr, &Len); \
+      Ptr += Len; \
+      /* NumToSkip is a plain 24-bit integer. */ \
+      unsigned NumToSkip = *Ptr++; \
+      NumToSkip |= (*Ptr++) << 8; \
+      NumToSkip |= (*Ptr++) << 16; \
+      /* Perform the decode operation. */ \
+      MCInst_setOpcode(MI, Opc); \
+      bool DecodeComplete; \
+      S = decoder(S, DecodeIdx, insn, MI, Address, Decoder, &DecodeComplete); \
+      if (DecodeComplete) { \
+        /* Decoding complete. */ \
+        return S; \
+      } else { \
+        /* If the decoding was incomplete, skip. */ \
+        Ptr += NumToSkip; \
+        /* Reset decode status. This also drops a SoftFail status that could be */ \
+        /* set before the decode attempt. */ \
+        S = MCDisassembler_Success; \
+      } \
+      break; \
+    } \
+    case MCD_OPC_SoftFail: { \
+      /* Decode the mask values. */ \
+      unsigned Len; \
+      uint64_t PositiveMask = decodeULEB128(++Ptr, &Len); \
+      Ptr += Len; \
+      uint64_t NegativeMask = decodeULEB128(Ptr, &Len); \
+      Ptr += Len; \
+      bool Fail = (insn & PositiveMask) != 0 || (~insn & NegativeMask) != 0; \
+      if (Fail) \
+        S = MCDisassembler_SoftFail; \
+      break; \
+    } \
+    case MCD_OPC_Fail: { \
+      return MCDisassembler_Fail; \
+    } \
+    } \
+  } \
+  /* Bogisity detected in disassembler state machine! */ \
+}
